function randomAluminumHexCode() {
  // Create an array of possible values for each character in the hex code
  const hexValues = '0123456789ABCDEF';

  // Initialize the hex code variable with a hashtag symbol
  let hexCode = '#';

  // Loop through 6 times to generate 6 characters for the hex code
  for (let i = 0; i < 6; i++) {
    // Generate a random index to select a character from the hexValues array
    const randomIndex = Math.floor(Math.random() * hexValues.length);

    // Append the selected character to the hexCode variable
    hexCode += hexValues[randomIndex];
  }

  // Return the random hexadecimal color code
  return hexCode;
}

